int x25_negotiate_facilities(struct sk_buff *skb, struct sock *sk, struct x25_facilities *new, struct x25_dte_facilities *dte) {
    int len = 0;
    u8 *data = skb->data;
    int data_len = skb->len;

    if (!skb || !sk || !new || !dte) {
        return -EINVAL;
    }

    if (data_len < 2) {
        return -EINVAL;
    }

    len = data[0];
    if (len > data_len - 1) {
        len = data_len - 1;
    }

    if (len < 2) {
        return -EINVAL;
    }

    new->throughput = data[1];
    new->window_size = data[2];
    new->packet_size = data[3];

    if (new->throughput > X25_MAX_THROUGHPUT) {
        new->throughput = X25_MAX_THROUGHPUT;
    }

    if (new->window_size > X25_MAX_WINDOW_SIZE) {
        new->window_size = X25_MAX_WINDOW_SIZE;
    }

    if (new->packet_size > X25_MAX_PACKET_SIZE) {
        new->packet_size = X25_MAX_PACKET_SIZE;
    }

    if (data[4] & X25_REVERSE_CHARGE_REQUEST) {
        new->reverse_charge = 1;
    }

    dte->throughput = data[5];
    dte->window_size = data[6];
    dte->packet_size = data[7];

    if (dte->throughput > X25_MAX_THROUGHPUT) {
        dte->throughput = X25_MAX_THROUGHPUT;
    }

    if (dte->window_size > X25_MAX_WINDOW_SIZE) {
        dte->window_size = X25_MAX_WINDOW_SIZE;
    }

    if (dte->packet_size > X25_MAX_PACKET_SIZE) {
        dte->packet_size = X25_MAX_PACKET_SIZE;
    }

    if (data[8] & X25_DTE_REVERSE_CHARGE_REQUEST) {
        dte->reverse_charge = 1;
    }

    return len;
}
